// vstoken.m -- EXP-0127 task 1: VS creation-order token derivation rule.
//
// CLEAN ROOM: public Metal API + OWN-SHADER only. Every function drawn here
// is compiled from our own committed MSL (kernels/vs_uniform.metal,
// kernels/vs_varied.metal, generated by analysis/gen_kernels.py). This
// program does not write into any live command-buffer memory (no splice);
// it only creates pipelines, draws, and (optionally) asks the unmodified,
// read-only tools/iotrace/iotrace.c interposer to snapshot this process's
// OWN registered GPU buffer objects via SIGUSR1, exactly as EXP-0042's
// multipipe.m/stage_matrix.m already do. Post-hoc Python analysis
// (analysis/analyze_vstoken.py) then reads those DATA-TRACE dumps to locate
// the VDM bind-pair token EXP-0042 already established at record+0x1c/+0x20.
//
// Two modes:
//   --mode varied: creates the 8 kernels/vs_varied.metal vertex functions in
//     a caller-specified order (--order "0,1,2,..." indices into the fixed
//     VARIED_NAMES table below, matching analysis/gen_kernels.py's
//     VARIED_SIZES list order) and draws each once. Distinguishes the
//     size-dependent-offset hypothesis (token step proportional to the
//     PRECEDING function's compiled code size) from the pure-ordinal
//     hypothesis (token step constant regardless of size).
//   --mode uniform: creates --count near-identical kernels/vs_uniform.metal
//     vertex functions (vs_u0000..vs_u{count-1}, ALL SAME nominal size) in
//     order and draws each once. Finds the token's step size, width/range,
//     and the resource-exhaustion boundary (first pipeline-creation
//     failure) for a long, same-size ordinal run.
//
// Safety: a per-draw watchdog (completion handler + timed semaphore, never
// a bare waitUntilCompleted) bounds any single command buffer; a pipeline
// CREATION failure is treated as a clean, expected boundary result and
// stops the sweep; a command-buffer HANG stops the sweep immediately with a
// distinct exit code so the driver does not blindly continue after a real
// device-level wedge signal. One process per mode invocation (run.py invokes
// this program up to twice: --mode varied once, --mode uniform once); no
// live command-stream memory is mutated by this program.
//
// Build:
//   xcrun clang -fobjc-arc -o vstoken vstoken.m -framework Metal -framework Foundation

#import <Metal/Metal.h>
#import <Foundation/Foundation.h>
#include <dispatch/dispatch.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static void fail(const char *what, NSError *error) {
    fprintf(stderr, "FAIL %s: %s\n", what,
            error ? error.localizedDescription.UTF8String : "unknown");
    exit(2);
}

// Fixed order matching analysis/gen_kernels.py's VARIED_SIZES table
// [0, 48, 4, 40, 12, 32, 20, 24] -> index i is vs_v{i:02d}_ops{size:03d}.
static const char *VARIED_NAMES[8] = {
    "vs_v00_ops000", "vs_v01_ops048", "vs_v02_ops004", "vs_v03_ops040",
    "vs_v04_ops012", "vs_v05_ops032", "vs_v06_ops020", "vs_v07_ops024",
};

typedef struct {
    id<MTLCommandBuffer> cb;
    dispatch_semaphore_t sem;
    __block MTLCommandBufferStatus status;
    __block NSString *errdesc;
} Watched;

static Watched *watch_commit(id<MTLCommandBuffer> cb, double timeout_sec) {
    Watched *w = calloc(1, sizeof(Watched));
    w->cb = cb;
    w->sem = dispatch_semaphore_create(0);
    dispatch_semaphore_t sem = w->sem;
    Watched *wref = w;
    [cb addCompletedHandler:^(id<MTLCommandBuffer> c) {
        wref->status = c.status;
        wref->errdesc = c.error ? c.error.localizedDescription : nil;
        dispatch_semaphore_signal(sem);
    }];
    [cb commit];
    long timed_out = dispatch_semaphore_wait(
        sem, dispatch_time(DISPATCH_TIME_NOW, (int64_t)(timeout_sec * NSEC_PER_SEC)));
    if (timed_out != 0) {
        w->status = (MTLCommandBufferStatus)-1; // sentinel: HANG
    }
    return w;
}

int main(int argc, char **argv) {
    @autoreleasepool {
        const char *mode = "varied";
        const char *source_varied = "kernels/vs_varied.metal";
        const char *source_uniform = "kernels/vs_uniform.metal";
        const char *order = "0,1,2,3,4,5,6,7";
        int count = 160;
        int dump = 0;
        int dump_first = 24;
        int dump_stride = 8;
        int dump_window_lo = -1, dump_window_hi = -1;
        double watchdog_sec = 12.0;
        unsigned proc_alarm = 900;
        int pad_mb = 0;
        int extra_queues = 0;
        int dump_sleep_ms = 500;

        for (int i = 1; i < argc; ++i) {
            if (!strcmp(argv[i], "--mode") && i + 1 < argc) mode = argv[++i];
            else if (!strcmp(argv[i], "--source-varied") && i + 1 < argc) source_varied = argv[++i];
            else if (!strcmp(argv[i], "--source-uniform") && i + 1 < argc) source_uniform = argv[++i];
            else if (!strcmp(argv[i], "--order") && i + 1 < argc) order = argv[++i];
            else if (!strcmp(argv[i], "--count") && i + 1 < argc) count = atoi(argv[++i]);
            else if (!strcmp(argv[i], "--dump")) dump = 1;
            else if (!strcmp(argv[i], "--dump-first") && i + 1 < argc) dump_first = atoi(argv[++i]);
            else if (!strcmp(argv[i], "--dump-stride") && i + 1 < argc) dump_stride = atoi(argv[++i]);
            else if (!strcmp(argv[i], "--dump-window") && i + 1 < argc) {
                sscanf(argv[++i], "%d,%d", &dump_window_lo, &dump_window_hi);
            }
            else if (!strcmp(argv[i], "--watchdog-sec") && i + 1 < argc) watchdog_sec = atof(argv[++i]);
            else if (!strcmp(argv[i], "--alarm") && i + 1 < argc) proc_alarm = (unsigned)atoi(argv[++i]);
            else if (!strcmp(argv[i], "--pad-mb") && i + 1 < argc) pad_mb = atoi(argv[++i]);
            else if (!strcmp(argv[i], "--extra-queues") && i + 1 < argc) extra_queues = atoi(argv[++i]);
            else if (!strcmp(argv[i], "--dump-sleep-ms") && i + 1 < argc) dump_sleep_ms = atoi(argv[++i]);
            else {
                fprintf(stderr, "usage: %s --mode varied|uniform [--order CSV] "
                        "[--count N] [--dump] [--dump-first K] [--dump-stride S] "
                        "[--dump-window LO,HI] [--watchdog-sec S] [--alarm SEC] "
                        "[--pad-mb N] [--extra-queues N]\n", argv[0]);
                return 2;
            }
        }
        alarm(proc_alarm);

        id<MTLDevice> device = MTLCreateSystemDefaultDevice();
        if (!device) { fprintf(stderr, "FAIL no Metal device\n"); return 2; }
        printf("DEVICE %s\n", device.name.UTF8String);
        printf("CONFIG mode=%s order=%s count=%d watchdog_sec=%.1f pad_mb=%d "
               "extra_queues=%d\n",
               mode, order, count, watchdog_sec, pad_mb, extra_queues);
        fflush(stdout);

        // Task 3 (P0.2 code-window relocation): allocate ordinary client
        // padding BEFORE any pipeline/library work, mirroring EXP-0110's
        // cdm_pad_big/vdm_pad_big method (16x4MiB buffers = 64MiB moved the
        // CDM chain but not the VDM/FF-state pool). Kept alive for the
        // whole process lifetime (not released) so the allocator cannot
        // reclaim it before pipelines are created.
        NSMutableArray<id<MTLBuffer>> *padding = [NSMutableArray array];
        if (pad_mb > 0) {
            const NSUInteger chunk = 4 * 1024 * 1024;
            int nchunks = (pad_mb * 1024 * 1024) / (int)chunk;
            for (int i = 0; i < nchunks; ++i) {
                id<MTLBuffer> b = [device newBufferWithLength:chunk
                                                      options:MTLResourceStorageModeShared];
                if (!b) { fprintf(stderr, "FAIL padding alloc %d\n", i); return 2; }
                memset(b.contents, 0x40 + (i & 0x3f), chunk);
                [padding addObject:b];
            }
            printf("PADDING allocated_mb=%d chunks=%d\n", pad_mb, nchunks);
            fflush(stdout);
        }
        // Extra prior queues, each actually used with a trivial dispatch-free
        // draw is not attempted here (would need a pipeline); mirroring
        // EXP-0110's pqN test at the granularity this harness supports, we
        // just create and retain N additional command queues before the
        // main queue/library/pipelines exist.
        NSMutableArray<id<MTLCommandQueue>> *extraq = [NSMutableArray array];
        for (int i = 0; i < extra_queues; ++i) {
            id<MTLCommandQueue> eq = [device newCommandQueue];
            if (!eq) { fprintf(stderr, "FAIL extra queue %d\n", i); return 2; }
            [extraq addObject:eq];
        }
        if (extra_queues > 0) { printf("EXTRAQUEUES created=%d\n", extra_queues); fflush(stdout); }

        NSError *error = nil;
        NSString *source_path = !strcmp(mode, "varied")
            ? @(source_varied) : @(source_uniform);
        NSString *source = [NSString stringWithContentsOfFile:source_path
                                                      encoding:NSUTF8StringEncoding
                                                         error:&error];
        if (!source) fail("read source", error);
        id<MTLLibrary> library = [device newLibraryWithSource:source options:nil error:&error];
        if (!library) fail("compile library", error);
        id<MTLFunction> fs_flat = [library newFunctionWithName:@"fs_flat"];
        if (!fs_flat) fail("missing fs_flat", nil);

        static const float tri[6] = {-1.0f, -1.0f, 3.0f, -1.0f, -1.0f, 3.0f};
        id<MTLBuffer> vertices = [device newBufferWithBytes:tri length:sizeof(tri)
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> colour = [device newBufferWithLength:0x100
                                                   options:MTLResourceStorageModeShared];
        float *cp = colour.contents;
        cp[0] = 0.2f; cp[1] = 0.4f; cp[2] = 0.6f; cp[3] = 1.0f;

        const NSUInteger width = 32, height = 32, bytes_per_row = 128;
        id<MTLBuffer> target_buffer = [device newBufferWithLength:bytes_per_row * height
                                                         options:MTLResourceStorageModeShared];
        MTLTextureDescriptor *td =
            [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                                               width:width height:height mipmapped:NO];
        td.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead;
        td.storageMode = MTLStorageModeShared;
        id<MTLTexture> target = [target_buffer newTextureWithDescriptor:td offset:0
                                                           bytesPerRow:bytes_per_row];
        if (!target) fail("target", nil);
        printf("RESOURCE vertices=0x%llx colour=0x%llx target=0x%llx\n",
               (unsigned long long)vertices.gpuAddress,
               (unsigned long long)colour.gpuAddress,
               (unsigned long long)target_buffer.gpuAddress);
        fflush(stdout);

        id<MTLCommandQueue> queue = [device newCommandQueue];

        int nfuncs = 0;
        NSMutableArray<NSString *> *names = [NSMutableArray array];
        if (!strcmp(mode, "varied")) {
            char *ord = strdup(order);
            char *tok = strtok(ord, ",");
            while (tok) {
                int idx = atoi(tok);
                if (idx < 0 || idx > 7) { fprintf(stderr, "FAIL bad order index %d\n", idx); return 2; }
                [names addObject:@(VARIED_NAMES[idx])];
                tok = strtok(NULL, ",");
            }
            free(ord);
            nfuncs = (int)names.count;
        } else if (!strcmp(mode, "uniform")) {
            for (int i = 0; i < count; ++i)
                [names addObject:[NSString stringWithFormat:@"vs_u%04d", i]];
            nfuncs = count;
        } else {
            fprintf(stderr, "FAIL unknown mode %s\n", mode);
            return 2;
        }

        for (int i = 0; i < nfuncs; ++i) {
            NSString *fname = names[i];
            id<MTLFunction> vfn = [library newFunctionWithName:fname];
            if (!vfn) {
                printf("RESULT i=%u name=%s stage=create status=missing_function\n",
                       i, fname.UTF8String);
                fflush(stdout);
                break;
            }
            MTLRenderPipelineDescriptor *desc = [MTLRenderPipelineDescriptor new];
            desc.label = fname;
            desc.vertexFunction = vfn;
            desc.fragmentFunction = fs_flat;
            desc.colorAttachments[0].pixelFormat = MTLPixelFormatBGRA8Unorm;
            NSError *perr = nil;
            id<MTLRenderPipelineState> state =
                [device newRenderPipelineStateWithDescriptor:desc error:&perr];
            if (!state) {
                printf("RESULT i=%u name=%s stage=create status=create_failed error=\"%s\"\n",
                       i, fname.UTF8String,
                       perr ? perr.localizedDescription.UTF8String : "unknown");
                fflush(stdout);
                printf("BOUNDARY create_failed_at=%u\n", i);
                fflush(stdout);
                break;
            }

            MTLRenderPassDescriptor *rp = [MTLRenderPassDescriptor renderPassDescriptor];
            rp.colorAttachments[0].texture = target;
            rp.colorAttachments[0].loadAction = MTLLoadActionClear;
            rp.colorAttachments[0].storeAction = MTLStoreActionStore;
            rp.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 1);
            id<MTLCommandBuffer> command = [queue commandBuffer];
            id<MTLRenderCommandEncoder> encoder =
                [command renderCommandEncoderWithDescriptor:rp];
            [encoder setRenderPipelineState:state];
            [encoder setVertexBuffer:vertices offset:0 atIndex:0];
            [encoder setFragmentBuffer:colour offset:0 atIndex:1];
            [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];
            [encoder endEncoding];

            Watched *w = watch_commit(command, watchdog_sec);
            int hang = (w->status == (MTLCommandBufferStatus)-1);
            int completed = (w->status == MTLCommandBufferStatusCompleted);
            printf("RESULT i=%u name=%s stage=draw status=%s final_status=%ld "
                   "error=\"%s\"\n",
                   i, fname.UTF8String,
                   hang ? "HANG" : (completed ? "completed" : "error"),
                   (long)w->status,
                   w->errdesc ? w->errdesc.UTF8String : "");
            fflush(stdout);

            int in_window = dump_window_lo >= 0 && i >= dump_window_lo && i <= dump_window_hi;
            int should_dump = dump && ((int)i < dump_first ||
                                        (dump_stride > 0 && (i % dump_stride) == 0) ||
                                        i == nfuncs - 1 || in_window);
            if (should_dump) {
                printf("DUMP i=%u\n", i);
                fflush(stdout);
                kill(getpid(), SIGUSR1);
                usleep((useconds_t)dump_sleep_ms * 1000);
            }
            free(w);

            if (hang) {
                printf("ABORT reason=hang at=%u\n", i);
                fflush(stdout);
                return 3;
            }
        }
        printf("DONE nfuncs=%d\n", nfuncs);
        alarm(0);
        return 0;
    }
}
